<?php

use App\Http\Controllers\Api\V1\AccessRoleController;
use App\Http\Controllers\Api\V1\AssignmentController;
use App\Http\Controllers\Api\V1\AuditLogController;
use App\Http\Controllers\Api\V1\AuthController;
use App\Http\Controllers\Api\V1\BranchController;
use App\Http\Controllers\Api\V1\CategoryController;
use App\Http\Controllers\Api\V1\CompanyController;
use App\Http\Controllers\Api\V1\CustomerController;
use App\Http\Controllers\Api\V1\ItemController;
use App\Http\Controllers\Api\V1\PlanController;
use App\Http\Controllers\Api\V1\PurchaseOrderController;
use App\Http\Controllers\Api\V1\ReportController;
use App\Http\Controllers\Api\V1\SaleController;
use App\Http\Controllers\Api\V1\ServiceOrderController;
use App\Http\Controllers\Api\V1\ShiftController;
use App\Http\Controllers\Api\V1\StockController;
use App\Http\Controllers\Api\V1\StockOpnameController;
use App\Http\Controllers\Api\V1\StockTransferController;
use App\Http\Controllers\Api\V1\SubscriptionController;
use App\Http\Controllers\Api\V1\SupplierController;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Route;

Route::middleware(['throttle:api', 'company.team'])->prefix('v1')->group(function (): void {
    Route::post('/auth/register', [AuthController::class, 'register']);
    Route::post('/auth/login', [AuthController::class, 'login']);

    Route::middleware(['auth:sanctum', 'scope.cabang', 'subscription.aktif'])->group(function (): void {
        Route::post('/auth/logout', [AuthController::class, 'logout']);
        Route::get('/auth/me', [AuthController::class, 'me']);
        Route::get('/companies', [CompanyController::class, 'index']);
        Route::post('/companies', [CompanyController::class, 'store']);
        Route::get('/companies/{company}/branches', [BranchController::class, 'index']);
        Route::post('/companies/{company}/branches', [BranchController::class, 'store'])->middleware('permission:cabang.kelola');
        Route::get('/companies/{company}/branches/{branch}', [BranchController::class, 'show']);
        Route::put('/companies/{company}/branches/{branch}', [BranchController::class, 'update'])->middleware('permission:cabang.kelola');
        Route::delete('/companies/{company}/branches/{branch}', [BranchController::class, 'destroy'])->middleware('permission:cabang.kelola');
        Route::get('/companies/{company}/categories', [CategoryController::class, 'index']);
        Route::post('/companies/{company}/categories', [CategoryController::class, 'store'])->middleware('permission:katalog.kelola');
        Route::get('/companies/{company}/categories/{category}', [CategoryController::class, 'show']);
        Route::put('/companies/{company}/categories/{category}', [CategoryController::class, 'update'])->middleware('permission:katalog.kelola');
        Route::delete('/companies/{company}/categories/{category}', [CategoryController::class, 'destroy'])->middleware('permission:katalog.kelola');
        Route::get('/companies/{company}/items', [ItemController::class, 'index']);
        Route::post('/companies/{company}/items', [ItemController::class, 'store'])->middleware('permission:katalog.kelola');
        Route::get('/companies/{company}/items/{item}', [ItemController::class, 'show']);
        Route::put('/companies/{company}/items/{item}', [ItemController::class, 'update'])->middleware('permission:katalog.kelola');
        Route::delete('/companies/{company}/items/{item}', [ItemController::class, 'destroy'])->middleware('permission:katalog.kelola');
        Route::put('/companies/{company}/items/{item}/prices/{branch}', [ItemController::class, 'setPrice'])->middleware('permission:harga.atur');
        Route::get('/companies/{company}/branches/{branch}/stock', [StockController::class, 'index']);
        Route::get('/companies/{company}/branches/{branch}/stock/movements', [StockController::class, 'movements']);
        Route::post('/companies/{company}/branches/{branch}/stock/movements', [StockController::class, 'store'])->middleware('permission:stok.opname');
        Route::get('/companies/{company}/stock-transfers', [StockTransferController::class, 'index']);
        Route::post('/companies/{company}/stock-transfers', [StockTransferController::class, 'store'])->middleware('permission:stok.transfer');
        Route::get('/companies/{company}/stock-transfers/{transfer}', [StockTransferController::class, 'show']);
        Route::post('/companies/{company}/stock-transfers/{transfer}/submit', [StockTransferController::class, 'submit'])->middleware('permission:stok.transfer');
        Route::post('/companies/{company}/stock-transfers/{transfer}/approve', [StockTransferController::class, 'approve'])->middleware('permission:stok.transfer');
        Route::post('/companies/{company}/stock-transfers/{transfer}/ship', [StockTransferController::class, 'ship'])->middleware('permission:stok.transfer');
        Route::post('/companies/{company}/stock-transfers/{transfer}/receive', [StockTransferController::class, 'receive'])->middleware('permission:stok.transfer');
        Route::post('/companies/{company}/stock-transfers/{transfer}/cancel', [StockTransferController::class, 'cancel'])->middleware('permission:stok.transfer');
        Route::get('/companies/{company}/branches/{branch}/stock/opnames', [StockOpnameController::class, 'index']);
        Route::post('/companies/{company}/branches/{branch}/stock/opnames', [StockOpnameController::class, 'store'])->middleware('permission:stok.opname');
        Route::get('/companies/{company}/branches/{branch}/stock/opnames/{opname}', [StockOpnameController::class, 'show']);
        Route::post('/companies/{company}/branches/{branch}/stock/opnames/{opname}/submit', [StockOpnameController::class, 'submit'])->middleware('permission:stok.opname');
        Route::post('/companies/{company}/branches/{branch}/stock/opnames/{opname}/approve', [StockOpnameController::class, 'approve'])->middleware('permission:stok.opname');
        Route::post('/companies/{company}/branches/{branch}/stock/opnames/{opname}/reject', [StockOpnameController::class, 'reject'])->middleware('permission:stok.opname');
        Route::get('/companies/{company}/suppliers', [SupplierController::class, 'index']);
        Route::post('/companies/{company}/suppliers', [SupplierController::class, 'store'])->middleware('permission:katalog.kelola');
        Route::get('/companies/{company}/suppliers/{supplier}', [SupplierController::class, 'show']);
        Route::put('/companies/{company}/suppliers/{supplier}', [SupplierController::class, 'update'])->middleware('permission:katalog.kelola');
        Route::delete('/companies/{company}/suppliers/{supplier}', [SupplierController::class, 'destroy'])->middleware('permission:katalog.kelola');
        Route::get('/companies/{company}/purchase-orders', [PurchaseOrderController::class, 'index']);
        Route::post('/companies/{company}/purchase-orders', [PurchaseOrderController::class, 'store'])->middleware('permission:po.buat');
        Route::get('/companies/{company}/purchase-orders/{order}', [PurchaseOrderController::class, 'show']);
        Route::post('/companies/{company}/purchase-orders/{order}/submit', [PurchaseOrderController::class, 'submit'])->middleware('permission:po.buat');
        Route::post('/companies/{company}/purchase-orders/{order}/approve', [PurchaseOrderController::class, 'approve'])->middleware('permission:po.setujui');
        Route::post('/companies/{company}/purchase-orders/{order}/order', [PurchaseOrderController::class, 'order'])->middleware('permission:po.setujui');
        Route::post('/companies/{company}/purchase-orders/{order}/receive', [PurchaseOrderController::class, 'receive'])->middleware('permission:po.setujui');
        Route::post('/companies/{company}/purchase-orders/{order}/cancel', [PurchaseOrderController::class, 'cancel'])->middleware('permission:po.setujui');
        Route::get('/companies/{company}/purchase-orders/{order}/receipts', [PurchaseOrderController::class, 'receipts']);
        Route::post('/companies/{company}/branches/{branch}/shifts', [ShiftController::class, 'open'])->middleware('permission:shift.buka');
        Route::get('/companies/{company}/branches/{branch}/shifts/{shift}', [ShiftController::class, 'show']);
        Route::post('/companies/{company}/branches/{branch}/shifts/{shift}/close', [ShiftController::class, 'close'])->middleware('permission:shift.tutup');
        Route::get('/companies/{company}/branches/{branch}/sales', [SaleController::class, 'index']);
        Route::post('/companies/{company}/branches/{branch}/sales', [SaleController::class, 'store'])->middleware('permission:transaksi.buat');
        Route::get('/companies/{company}/branches/{branch}/sales/{sale}', [SaleController::class, 'show']);
        Route::post('/companies/{company}/branches/{branch}/sales/{sale}/void', [SaleController::class, 'void'])->middleware('permission:transaksi.void');
        Route::get('/companies/{company}/branches/{branch}/returns', [SaleController::class, 'returns']);
        Route::post('/companies/{company}/branches/{branch}/sales/{sale}/returns', [SaleController::class, 'storeReturn'])->middleware('permission:retur.buat');
        Route::get('/companies/{company}/customers', [CustomerController::class, 'index']);
        Route::post('/companies/{company}/customers', [CustomerController::class, 'store'])->middleware('permission:pelanggan.kelola');
        Route::get('/companies/{company}/customers/{customer}', [CustomerController::class, 'show']);
        Route::put('/companies/{company}/customers/{customer}', [CustomerController::class, 'update'])->middleware('permission:pelanggan.kelola');
        Route::delete('/companies/{company}/customers/{customer}', [CustomerController::class, 'destroy'])->middleware('permission:pelanggan.kelola');
        Route::get('/companies/{company}/branches/{branch}/service-orders', [ServiceOrderController::class, 'index']);
        Route::post('/companies/{company}/branches/{branch}/service-orders', [ServiceOrderController::class, 'store'])->middleware('permission:transaksi.buat');
        Route::get('/companies/{company}/branches/{branch}/service-orders/{order}', [ServiceOrderController::class, 'show']);
        Route::post('/companies/{company}/branches/{branch}/service-orders/{order}/deposit', [ServiceOrderController::class, 'deposit'])->middleware('permission:transaksi.buat');
        Route::post('/companies/{company}/branches/{branch}/service-orders/{order}/process', [ServiceOrderController::class, 'process'])->middleware('permission:transaksi.buat');
        Route::post('/companies/{company}/branches/{branch}/service-orders/{order}/complete', [ServiceOrderController::class, 'complete'])->middleware('permission:transaksi.buat');
        Route::post('/companies/{company}/branches/{branch}/service-orders/{order}/pay', [ServiceOrderController::class, 'pay'])->middleware('permission:transaksi.buat');
        Route::post('/companies/{company}/branches/{branch}/service-orders/{order}/cancel', [ServiceOrderController::class, 'cancel'])->middleware('permission:transaksi.buat');
        Route::get('/companies/{company}/audit-logs', [AuditLogController::class, 'index'])->middleware('permission:audit.lihat');
        Route::get('/plans', [PlanController::class, 'index']);
        Route::post('/plans', [PlanController::class, 'store'])->middleware('super.admin');
        Route::get('/plans/{plan}', [PlanController::class, 'show']);
        Route::put('/plans/{plan}', [PlanController::class, 'update'])->middleware('super.admin');
        Route::delete('/plans/{plan}', [PlanController::class, 'destroy'])->middleware('super.admin');
        Route::get('/companies/{company}/subscription', [SubscriptionController::class, 'show']);
        Route::put('/companies/{company}/subscription', [SubscriptionController::class, 'update'])->middleware('super.admin');
        Route::get('/companies/{company}/reports/daily', [ReportController::class, 'daily'])->middleware('permission:keuangan.lihat');
        Route::get('/companies/{company}/reports/consolidation', [ReportController::class, 'consolidation'])->middleware('permission:laporan.konsolidasi');
        Route::post('/companies/{company}/reports/refresh', [ReportController::class, 'refresh'])->middleware('permission:laporan.konsolidasi');

        Route::prefix('/companies/{company}/access')->group(function (): void {
            Route::get('/permissions', [AccessRoleController::class, 'permissions']);
            Route::get('/templates', [AccessRoleController::class, 'templates']);
            Route::get('/roles', [AccessRoleController::class, 'index']);
            Route::post('/roles', [AccessRoleController::class, 'store'])->middleware('permission:pengaturan.kelola');
            Route::get('/roles/{role}', [AccessRoleController::class, 'show']);
            Route::put('/roles/{role}', [AccessRoleController::class, 'update'])->middleware('permission:pengaturan.kelola');
            Route::delete('/roles/{role}', [AccessRoleController::class, 'destroy'])->middleware('permission:pengaturan.kelola');
            Route::post('/users/{user}/roles', [AccessRoleController::class, 'assign'])->middleware('permission:karyawan.kelola');
            Route::delete('/users/{user}/roles/{role}', [AccessRoleController::class, 'revoke'])->middleware('permission:karyawan.kelola');
            Route::get('/assignments', [AssignmentController::class, 'index']);
            Route::post('/users/{user}/assignments', [AssignmentController::class, 'store'])->middleware('permission:karyawan.kelola');
            Route::get('/assignments/{assignment}', [AssignmentController::class, 'show']);
            Route::post('/assignments/{assignment}/close', [AssignmentController::class, 'close'])->middleware('permission:karyawan.kelola');
        });
    });
});

Route::get('/user', function (Request $request) {
    return $request->user();
})->middleware('auth:sanctum');
